static void
async_result_cb (GObject      *obj,
                 GAsyncResult *result,
                 void         *user_data)
{
  GAsyncResult **result_out = user_data;

  g_assert (result_out != NULL);
  g_assert (*result_out == NULL);

  *result_out = g_object_ref (result);
  g_main_context_wakeup (g_main_context_get_thread_default ());
}

